package com.airesumebuilder.feature.subscription.controller;import com.airesumebuilder.common.dto.ApiResponse;import com.airesumebuilder.feature.subscription.service.SubscriptionService;import com.airesumebuilder.security.CurrentUser;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/subscriptions")public class SubscriptionController{private final SubscriptionService service;private final CurrentUser user;public SubscriptionController(SubscriptionService s,CurrentUser u){service=s;user=u;}@GetMapping("/current")public ResponseEntity<ApiResponse<SubscriptionService.Subscription>>current(){return ResponseEntity.ok(ApiResponse.success(service.current(user.email()),"Subscription retrieved."));}@GetMapping("/history")public ResponseEntity<ApiResponse<List<SubscriptionService.Subscription>>>history(){return ResponseEntity.ok(ApiResponse.success(service.history(user.email()),"Subscription history retrieved."));}@PostMapping("/cancel")public ResponseEntity<ApiResponse<SubscriptionService.Subscription>>cancel(){return ResponseEntity.ok(ApiResponse.success(service.cancel(user.email()),"Subscription cancelled; free plan activated."));}}
